'use client';
import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { Brand } from '../lib/brands';
import { cx } from '../lib/cx';
import { useCopied } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { usePopover } from '../lib/popover';
import { avatarInk, Swap, Tip } from '../lib/motion';
import '../designme.css';
import './meeting-card.css';

export interface MeetingCardAction {
  key: string;
  label: string;
  icon?: IconName;
  /** What the chevron says once it is done, like "Invite sent". Defaults to the label */
  done?: string;
}

const ACTIONS: MeetingCardAction[] = [
  { key: 'invite', label: 'Send invite', icon: 'mail', done: 'Invite sent' },
  { key: 'calendar', label: 'Add to calendar', icon: 'cal', done: 'Added to calendar' },
  { key: 'copy', label: 'Copy invitation', icon: 'copy', done: 'Invitation copied' }
];

export interface MeetingCardPerson {
  /** Like "MK" */
  initials: string;
  /** The avatar's colour, like 'var(--dm-av-l)' */
  color: string;
  /** Shown in the avatar's tooltip and read by screen readers, like "Maya Kim" */
  name: string;
}

export interface MeetingCardProps {
  /** Like "Pricing review" */
  title: string;
  /** The line under the title. Defaults to "Today, 10:30 to 11:15" from `start` and `end` */
  subtitle?: string;
  /** When it starts, 24-hour "HH:MM", like "10:30" */
  start: string;
  /** When it ends, like "11:15" */
  end: string;
  /** The time now, like "10:20". The status chip, the now line and the hatched past all follow it */
  now: string;
  /** Where the track starts. Defaults to half an hour before `start` */
  from?: string;
  /** Where the track ends. Defaults to half an hour after `end` */
  to?: string;
  /** Who is invited, as an avatar stack with each name in a tooltip */
  people?: MeetingCardPerson[];
  /** How many avatars show before a "+N". Defaults to 4 */
  max?: number;
  /** The status chip's text, in place of the countdown: "In 10 min", "Starting now", "Live, 30 min left", "Ended" */
  status?: string;
  /** The call's service, for names and labels. Defaults to "Google Meet" */
  provider?: string;
  /** The service's mark on the Join button. Defaults to the Google Meet mark */
  mark?: ReactNode;
  /** The call's link, like "meet.google.com/nax-wqkf-stu" */
  link: string;
  /** Where joining goes and what is copied. Defaults to the link over https */
  href?: string;
  /** Called on Join. Left out, the link opens in a new tab */
  onJoin?: () => void;
  onCopy?: (url: string) => void;
  /** Defaults to "Join" */
  joinLabel?: string;
  /** The copy button's tooltip. Defaults to "Copy" and the link */
  copyLabel?: string;
  /** The tooltip after copying. Defaults to "Copied" */
  copiedLabel?: string;
  /** The menu under the chevron beside Join. Defaults to Send invite, Add to calendar and Copy invitation; [] hides the chevron */
  actions?: MeetingCardAction[];
  /** Called with the picked action's key. Copy invitation also copies the title, the time and the link */
  onAction?: (key: string) => void;
  className?: string;
}

const mins = (t: string) => { const [h, m] = t.split(':').map(Number); return h * 60 + (m || 0); };
const clock = (m: number) => `${Math.floor(m / 60)}:${String(m % 60).padStart(2, '0')}`;

/** The next meeting, from countdown to wrap-up: a status chip that counts down, says "Starting now", then the minutes left,
    and "Ended"; a track with the meeting on it, the time already gone hatched out; the people invited; and Join, which
    stays open while the meeting runs. */
export function MeetingCard({ title, subtitle, start, end, now, from, to, people = [], max = 4, status, provider = 'Google Meet', mark,
  link, href, onJoin, onCopy, joinLabel = 'Join', copyLabel, copiedLabel = 'Copied', actions = ACTIONS, onAction, className }: MeetingCardProps) {
  const a = mins(start), b = mins(end), t = mins(now);
  const lo = from ? mins(from) : a - 30, hi = to ? mins(to) : b + 30, span = Math.max(1, hi - lo);
  const pc = (m: number) => Math.min(100, Math.max(0, (m - lo) / span * 100));
  const phase = t < a ? 'soon' : t === a ? 'start' : t < b ? 'live' : 'done';
  const n = phase === 'soon' ? a - t : b - t;
  const url = href ?? 'https://' + link.replace(/^https?:\/\//, '');
  const [copied, copy] = useCopied();
  // a new state fades in, and within a state only the minutes roll; nothing moves on the first render
  const ready = useRef(false);
  useEffect(() => { ready.current = true; }, []);
  const roll = <span className="dm-mtx-roll dm-num"><i key={n} className={ready.current ? 'dm-in' : undefined}>{n}</i></span>;
  const chip = status ?? null;
  // Join presses with a small settle and says it is opening for a moment
  const [label, setLabel] = useState(joinLabel), [pressed, setPressed] = useState(false);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(() => () => timers.current.forEach(clearTimeout), []);
  useEffect(() => setLabel(joinLabel), [joinLabel]);
  const join = () => {
    setPressed(true); setLabel(`Opening ${provider.split(' ').pop()}`);
    timers.current.push(setTimeout(() => setPressed(false), 110), setTimeout(() => setLabel(joinLabel), 1600));
    if (onJoin) onJoin(); else window.open(url, '_blank', 'noopener');
  };
  // the meeting's actions: the chevron flashes a check and its tooltip says what happened
  const menu = usePopover({ align: 'end' });
  const [did, setDid] = useState<string | null>(null);
  const act = (a: MeetingCardAction) => {
    if (a.key === 'copy') { try { navigator.clipboard.writeText(`${title}, ${subtitle ?? `today ${start} to ${end}`}\n${url}`).catch(() => {}); } catch { /* no clipboard */ } }
    onAction?.(a.key); menu.closeSoon();
    timers.current.push(setTimeout(() => setDid(a.done ?? a.label), 140), setTimeout(() => setDid(null), 1640));
  };
  const shown = people.slice(0, max), rest = people.slice(max);
  const live = phase === 'start' || phase === 'live';
  const past = { ['--dm-p' as string]: pc(t) + '%' } as CSSProperties;

  return (
    <div data-dm="" className={cx('dm-mtx dm-panel', live && 'dm-live', phase === 'done' && 'dm-done', className)}>
      <div className="dm-mtx-h">
        <b className="dm-mtx-t">{title}</b><span className="dm-mtx-sub dm-num">{subtitle ?? `Today, ${start} to ${end}`}</span>
        <span className={cx('dm-tag dm-mtx-st', live && 'dm-ok')}>
          <span key={chip ?? phase} className={ready.current ? 'dm-mtx-fade' : undefined}>
            {chip ?? (phase === 'soon' ? <><Icon name="clock" size="xs" />In {roll} min</>
              : phase === 'start' ? <><i className="dm-dot" />Starting now</>
              : phase === 'live' ? <><i className="dm-dot" />Live, {roll} min left</> : 'Ended')}
          </span>
        </span>
      </div>
      <div className="dm-mtx-track" style={past} role="img"
        aria-label={phase === 'done' ? `The meeting ran ${start} to ${end} and has ended` : `Now ${clock(t)}. The meeting runs ${start} to ${end}`}>
        <span className="dm-mtx-blk" style={{ left: pc(a) + '%', width: pc(b) - pc(a) + '%', ['--dm-cut' as string]: Math.min(100, Math.max(0, (t - a) / Math.max(1, b - a) * 100)) + '%' }}>
          <span className="dm-mtx-bp" /><span className="dm-num">{start}</span><span className="dm-num">{end}</span>
        </span>
        <span className="dm-mtx-now"><i /></span>
      </div>
      <div className="dm-mtx-f">
        <div className="dm-mtx-who">
          {shown.map(p => (
            <Tip key={p.name} label={p.name}>
              <span className="dm-av" role="img" aria-label={p.name} style={{ background: p.color, color: avatarInk(p.color) }}>{p.initials}</span>
            </Tip>
          ))}
          {rest.length > 0 && (
            <Tip label={rest.map(p => p.name).join(', ')}>
              <span className="dm-av dm-mtx-more" role="img" aria-label={rest.map(p => p.name).join(', ')}>+{rest.length}</span>
            </Tip>
          )}
        </div>
        <span className="dm-sp" />
        <Tip label={copied ? copiedLabel : copyLabel ?? `Copy ${link}`} open={copied || undefined}>
          <button type="button" className={cx('dm-ib dm-mtx-cp', copied && 'dm-copied')} aria-label={`Copy ${provider} link`} onClick={() => { copy(url); onCopy?.(url); }}>
            <Icon name={copied ? 'check' : 'link'} />
          </button>
        </Tip>
        <div className="dm-mtx-jg">
          <button type="button" className={cx('dm-pill dm-primary dm-mtx-join', pressed && 'dm-prs')} disabled={phase === 'done'} onClick={join}>
            <span className="dm-mk">{mark ?? <Brand name="meet" />}</span><Swap className="dm-lb">{label}</Swap>
          </button>
          {actions.length > 0 && <>
            <Tip label={did ?? ''} open={did ? true : undefined} off={!did}>
              <button type="button" {...menu.trigger} className={cx('dm-pill dm-primary dm-mtx-jm', did && 'dm-done')} aria-label="More for this meeting" disabled={phase === 'done'}>
                <Icon name={did ? 'check' : 'chev-d'} size="xs" />
              </button>
            </Tip>
            <div {...menu.pop} className={cx(menu.pop.className, 'dm-mtx-pop')} role="menu">
              {actions.map(a => (
                <button key={a.key} type="button" role="menuitem" className="dm-mi" onClick={() => act(a)}>{a.icon && <Icon name={a.icon} />}{a.label}</button>
              ))}
            </div>
          </>}
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Meeting card ---------- */
/* the next meeting, told as it goes: a countdown, "Starting now", the meeting in progress and then over. The track is the
   morning from 10:00 to 12:30 with the meeting on it in the accent tint, its start and end on the block itself. Time that
   has gone is hatched out in neutral grey (the hatch and the tint meet at the now line), and the status chip at the top right
   rolls its minutes. Join stays open while the meeting runs, since people join late, and breathes gently while it is live.
   Every state is the same height */
.dm-mtx{width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4)}
/* the title and the chip share the first line; the time runs under both, so a longer chip never wraps it and every state
   is the same height */
.dm-mtx-h{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);row-gap:2px}
.dm-mtx-t{font-size:14px;font-weight:500;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-mtx-sub{grid-row:2;grid-column:1 / -1;font-size:12.5px;color:var(--dm-muted)}
.dm-mtx-st{grid-row:1;grid-column:2;justify-self:end;transition:background .4s cubic-bezier(.22,1,.36,1),color .4s cubic-bezier(.22,1,.36,1)}
.dm-mtx-st>span{display:inline-flex;align-items:center;gap:5px}
.dm-mtx-st .dm-dot{color:var(--dm-ok-mark)}
.dm-mtx-fade{animation:dm-mtxfade .4s cubic-bezier(.22,1,.36,1) both}
@keyframes dm-mtxfade{from{opacity:0}}
/* the minutes roll: each new number comes up from below */
/* the rolling minutes keep the chip's own line, so the number sits on the words' baseline (owner, 17 Nov) */
.dm-mtx-roll{display:inline-grid;overflow:hidden;line-height:inherit;height:1lh}
.dm-mtx-roll i{font-style:normal}
.dm-mtx-roll i.dm-in{animation:dm-mtxroll .32s cubic-bezier(.22,1,.36,1) both}
@keyframes dm-mtxroll{from{transform:translateY(70%);opacity:0}}
/* the track: the morning on a quiet row, the meeting on it */
.dm-mtx-track{position:relative;height:40px;border-radius:calc(8px * var(--dm-rk));background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);overflow:hidden}
/* Blueprint's row is the surface itself: its green now line keeps 3:1 on white, not on the row grey */
:root:not([data-style="soft"],[data-style="clean"]) .dm-mtx-track:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:var(--dm-surface)}
.dm-mtx-blk{position:absolute;top:5px;bottom:5px;left:20%;width:60%;display:flex;align-items:center;justify-content:space-between;padding:0 6px;border-radius:calc(5px * var(--dm-rk));background:var(--dm-accent-bg);overflow:hidden;font-size:11.5px;font-weight:500;color:var(--dm-fg2);z-index:1}
/* the start and end sit on the block in small surface chips, so they read on the tint and on the hatch alike; the block's
   edge is a faint accent line (owner, 17 Nov: no grey outline) */
.dm-mtx-blk{outline:1px solid color-mix(in srgb,var(--dm-accent-mark) 35%,transparent);outline-offset:-1px}
.dm-mtx-blk>.dm-num{position:relative;padding:0 6px;line-height:18px;border-radius:calc(4px * var(--dm-rk));background:color-mix(in srgb,var(--dm-surface) 88%,transparent);color:var(--dm-fg2)}
/* dark: raised means lighter, so the chip is the tint lifted a step, opaque enough to clear the hatch (owner, 17 Nov) */
:root[data-theme="dark"] .dm-mtx-blk>.dm-num{background:color-mix(in srgb,var(--dm-fg) 12%,var(--dm-accent-bg));color:var(--dm-fg)}
/* gone: fine 45deg accent lines over the tint, inside the meeting block only, across the part that has run (owner, 17 Nov) */
.dm-mtx-bp{position:absolute;top:0;bottom:0;left:0;background:repeating-linear-gradient(45deg,color-mix(in srgb,var(--dm-accent-mark) 60%,transparent) 0 1px,transparent 1px 6px);transition:width .45s cubic-bezier(.22,1,.36,1)}
.dm-mtx-bp{width:var(--dm-cut,0%)}
.dm-mtx-now{position:absolute;top:0;bottom:0;left:var(--dm-p,0%);width:2px;margin-left:-1px;background:var(--dm-accent-mark);transition:left .45s cubic-bezier(.22,1,.36,1);z-index:2}
.dm-mtx-now i{position:absolute;top:3px;left:50%;width:6px;height:6px;margin-left:-3px;border-radius:50%;background:var(--dm-accent-mark)}
.dm-mtx.dm-done .dm-mtx-now{opacity:0;transition:opacity .4s,left .45s cubic-bezier(.22,1,.36,1)}
/* the footer: who is coming, the link, and Join */
.dm-mtx-f{display:flex;align-items:center;gap:var(--dm-s-2)}
.dm-mtx-who{display:flex;align-items:center;padding:2px 0}
.dm-mtx-who .dm-av{width:26px;height:26px;font-size:10px;margin-left:-4px;box-shadow:0 0 0 2px var(--dm-surface);transition:margin .25s cubic-bezier(.22,1,.36,1)}
.dm-mtx-who .dm-av:first-child{margin-left:0}
/* small phones: the people overlap a little more so the split Join keeps the card's padding */
@media (max-width:400px){.dm-mtx-who .dm-av:not(:first-child){margin-left:-9px}}
@media (hover:hover) and (pointer:fine){.dm-mtx-who:is(:hover,.dm-hv) .dm-av:not(:first-child){margin-left:2px}}
.dm-mtx-who .dm-mtx-more{background:var(--dm-chip);color:var(--dm-fg2)}
/* art/art.js writes the face inline over the avatar's inline colour, so these have to win over the inline style */
.dm-mtx-who .dm-av[data-pic-on]{background-size:cover!important;background-position:center!important;background-repeat:no-repeat!important;color:transparent!important}
/* the copy button's hover a step darker than the row grey, so it reads in light (owner, 17 Nov) */
@media (hover:hover) and (pointer:fine){.dm-mtx-cp:hover{background:color-mix(in srgb,var(--dm-fg) 9%,transparent);color:var(--dm-fg)}}
/* Join and its menu as one split button: a very light divider, a chevron that opens the meeting's actions */
.dm-mtx-jg{position:relative;display:flex;flex:none}
.dm-mtx-jg .dm-mtx-join{border-top-right-radius:0;border-bottom-right-radius:0;padding-right:var(--dm-s-3)}
.dm-mtx-jm{position:relative;height:34px;width:30px;padding:0;justify-content:center;border-top-left-radius:0;border-bottom-left-radius:0}
.dm-mtx-jm::before{content:"";position:absolute;left:0;top:9px;bottom:9px;width:1px;background:color-mix(in srgb,var(--dm-on-accent) 30%,transparent)}
.dm-mtx-jm.dm-done{color:var(--dm-on-accent)}
.dm-mtx-pop{min-width:190px}
.dm-mtx-cp{width:34px;height:34px}
.dm-mtx-join{height:34px;padding:0 var(--dm-s-4) 0 6px;gap:var(--dm-s-2);transition:background var(--dm-t-fast),opacity var(--dm-t-fast),transform .32s cubic-bezier(.34,1.56,.64,1)}
.dm-mtx-join:active,.dm-mtx-join.dm-prs{transform:scale(.95);transition-duration:.08s}
.dm-mtx-join .dm-mk{width:22px;height:22px;display:grid;place-items:center;border-radius:calc(6px * var(--dm-rk));background:#fff;flex:none}
.dm-mtx-join .dm-mk .dm-brand{width:15px;height:12.5px}
/* live: Join breathes a step darker and back, slowly; a darker fill keeps its label's contrast where fading it would not */
.dm-mtx.dm-live :is(.dm-mtx-join,.dm-mtx-jm):not(:hover){animation:dm-mtxpulse 2.4s ease-in-out infinite}
@keyframes dm-mtxpulse{50%{background:color-mix(in srgb,var(--dm-accent) 86%,#000)}}
.dm-mtx-join[disabled] .dm-mk{opacity:.5}
@media (prefers-reduced-motion:reduce){.dm-mtx.dm-live :is(.dm-mtx-join,.dm-mtx-jm){animation:none}.dm-mtx-bp,.dm-mtx-now,.dm-mtx-who .dm-av{transition:none}.dm-mtx-roll i.dm-in,.dm-mtx-fade{animation:none}}
